def handle(query, state):
    vfs = state.get('vault', {})
    base = '/var/assets'

    requested = (query.get('asset') or [''])[0]
    if not requested:
        return 200, {'Content-Type': 'text/plain'}, 'Asset server: use ?asset=file.dat'

    if requested.startswith('/'):
        return 403, {'Content-Type': 'text/plain'}, 'Forbidden: no absolute paths'

    full_path = base + '/' + requested
    content = vfs.get(full_path)
    if content is None:
        return 404, {'Content-Type': 'text/plain'}, 'Asset not found: ' + requested + '\n'

    return 200, {'Content-Type': 'text/plain'}, content
